  "content": "import json
import os
import subprocess
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
MON = ROOT / "monitor"
NOTES = ROOT.parent / "shared_notes"
PROJ = Path.home() / ".claude/projects/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I"
SESSION = "c4794a53-4881-4aa9-8b9b-7c033457fa8b"
PERIOD = float(os.environ.get("MON_PERIOD", 120))
LIFETIME_H = float(os.environ.get("MON_LIFETIME_H", 96))


def utcnow():
    return datetime.now(timezone.utc)


def iso(t):
    return t.strftime("%Y-%m-%dT%H:%M:%SZ")


def transcripts():
    main = PROJ / f"{SESSION}.jsonl"
    files = [main] if main.exists() else []
    sub = PROJ / SESSION
    if sub.exists():
        files += sorted(sub.rglob("*.jsonl"))
    return files


def start_time():
    cache = MON / "start.json"
    if cache.exists():
        return datetime.fromisoformat(json.loads(cache.read_text())["start_utc"].replace("Z", "+00:00"))
    for line in open(PROJ / f"{SESSION}.jsonl"):
        try:
            d = json.loads(line)
        except ValueError:
            continue
        if d.get("type") == "user" and "mhd_llm/claude" in json.dumps(d.get("message", "")):
            t = datetime.fromisoformat(d["timestamp"].replace("Z", "+00:00"))
            cache.write_text(json.dumps({"start_utc": iso(t)}))
            return t
    return utcnow()


_tok_cache = {}


def tokens():
    usage = {}
    for f in transcripts():
        st = f.stat()
        key = (st.st_size, st.st_mtime)
        if _tok_cache.get(f, (None,))[0] != key:
            ids = {}
            with open(f) as fh:
                for line in fh:
                    if '"usage"' not in line:
                        continue
                    try:
                        m = json.loads(line).get("message")
                    except ValueError:
                        continue
                    if isinstance(m, dict) and m.get("usage") and m.get("id"):
                        ids[m["id"]] = m["usage"]
            _tok_cache[f] = (key, ids)
        usage.update(_tok_cache[f][1])
    tot = {"input": 0, "cache_write": 0, "cache_read": 0, "output": 0}
    for u in usage.values():
        tot["input"] += u.get("input_tokens", 0) or 0
        tot["cache_write"] += u.get("cache_creation_input_tokens", 0) or 0
        tot["cache_read"] += u.get("cache_read_input_tokens", 0) or 0
        tot["output"] += u.get("output_tokens", 0) or 0
    tot["fresh"] = tot["input"] + tot["cache_write"] + tot["output"]
    tot["all"] = tot["fresh"] + tot["cache_read"]
    tot["api_calls"] = len(usage)
    tot["transcripts"] = len(transcripts())
    return tot


def sh(cmd):
    try:
        return subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=20).stdout.strip()
    except Exception:
        return ""


def compute():
    load = open("/proc/loadavg").read().split()[:3]
    mem = {}
    for line in open("/proc/meminfo"):
        k, v = line.split(":")
        mem[k] = int(v.split()[0]) / 1048576
    g = sh("nvidia-smi --query-gpu=utilization.gpu,memory.used,memory.total,power.draw,temperature.gpu --format=csv,noheader,nounits")
    gpu = [x.strip() for x in g.split(",")] if g else []
    apps = sh("nvidia-smi --query-compute-apps=pid,used_memory --format=csv,noheader,nounits")
    mine_cpu = 0.0
    mine_rss = 0.0
    mine_pids = []
    for p in Path("/proc").iterdir():
        if not p.name.isdigit():
            continue
        try:
            cmd = (p / "cmdline").read_bytes().replace(b"\0", b" ").decode(errors="ignore")
            cwd = os.readlink(p / "cwd")
        except Exception:
            continue
        if "mhd_llm/claude" in cmd or "mhd_llm/claude" in cwd:
            if "monitor.py" in cmd:
                continue
            try:
                stat = (p / "stat").read_text().split()
                mine_cpu += (int(stat[13]) + int(stat[14])) / os.sysconf("SC_CLK_TCK")
                for line in open(p / "status"):
                    if line.startswith("VmRSS"):
                        mine_rss += int(line.split()[1]) / 1048576
                mine_pids.append(p.name)
            except Exception:
                pass
    gpu_mine = 0.0
    for row in apps.splitlines():
        parts = [x.strip() for x in row.split(",")]
        if len(parts) == 2 and parts[0] in mine_pids:
            try:
                gpu_mine += float(parts[1]) / 1024
            except ValueError:
                pass
    return {
        "load1_5_15": [float(x) for x in load],
        "mem_avail_gb": round(mem.get("MemAvailable", 0), 2),
        "mem_total_gb": round(mem.get("MemTotal", 0), 2),
        "swap_used_gb": round(mem.get("SwapTotal", 0) - mem.get("SwapFree", 0), 2),
        "gpu_util_pct": float(gpu[0]) if gpu else None,
        "gpu_mem_used_gb": round(float(gpu[1]) / 1024, 2) if gpu else None,
        "gpu_power_w": float(gpu[3]) if len(gpu) > 3 and gpu[3] not in ("[N/A]", "") else None,
        "gpu_temp_c": float(gpu[4]) if len(gpu) > 4 else None,
        "claude_procs": len(mine_pids),
        "claude_proc_cpu_s_live": round(mine_cpu, 1),
        "claude_proc_rss_gb": round(mine_rss, 2),
        "claude_gpu_mem_gb": round(gpu_mine, 2),
    }


def progress(elapsed_h):
    path = MON / "progress.json"
    try:
        p = json.loads(path.read_text())
    except Exception:
        return {"fraction": None, "eta_h": None}
    w = sum(m["weight"] for m in p["milestones"])
    done = sum(m["weight"] * m.get("done", 0) for m in p["milestones"])
    frac = done / w if w else 0
    eta = elapsed_h * (1 - frac) / frac if frac > 0.02 else None
    nxt = [m["name"] for m in p["milestones"] if m.get("done", 0) < 1][:3]
    return {"fraction": round(frac, 3), "eta_h": round(eta, 1) if eta else None, "next": nxt}


def note_state():
    state = {}
    if NOTES.exists():
        for f in NOTES.rglob("*"):
            if f.is_file():
                st = f.stat()
                state[str(f.relative_to(NOTES))] = (st.st_mtime, st.st_size)
    return state


def emit(msg):
    line = f"{iso(utcnow())} {msg}"
    print(line, flush=True)
    with open(MON / "events.log", "a") as fh:
        fh.write(line + "\n")


def main():
    t0 = start_time()
    born = time.time()
    seen = note_state()
    seen_path = MON / "notes_seen.json"
    if seen_path.exists():
        seen = {k: tuple(v) for k, v in json.loads(seen_path.read_text()).items()}
    cpu_acc_path = MON / "cpu_accum.json"
    acc = json.loads(cpu_acc_path.read_text()) if cpu_acc_path.exists() else {"gpu_busy_s": 0.0, "cpu_core_s_est": 0.0}
    last = time.time()
    last_hb = 0
    while not (MON / "STOP").exists() and time.time() - born < LIFETIME_H * 3600:
        now = utcnow()
        dt = time.time() - last
        last = time.time()
        el_h = (now - t0).total_seconds() / 3600
        c = compute()
        if c["gpu_util_pct"] is not None and c["claude_gpu_mem_gb"] > 0:
            acc["gpu_busy_s"] += dt * c["gpu_util_pct"] / 100
        acc["cpu_core_s_est"] += dt * min(c["claude_procs"], 1) * 0
        cpu_acc_path.write_text(json.dumps(acc))
        tok = tokens()
        pr = progress(el_h)
        cur = note_state()
        for k, v in cur.items():
            if k not in seen or tuple(seen[k]) != tuple(v):
                who = "self" if Path(k).name.startswith("claude_") else "COLLABORATOR"
                if who == "COLLABORATOR":
                    emit(f"NOTE {'new' if k not in seen else 'updated'} by collaborator: shared_notes/{k}")
        seen = cur
        seen_path.write_text(json.dumps(seen))
        status = {
            "updated_utc": iso(now),
            "project_start_utc": iso(t0),
            "runtime_h": round(el_h, 3),
            "compute": c,
            "gpu_busy_s_claude": round(acc["gpu_busy_s"], 1),
            "tokens": tok,
            "progress": pr,
        }
        (MON / "status.json").write_text(json.dumps(status, indent=1))
        with open(MON / "log.tsv", "a") as fh:
            if fh.tell() == 0:
                fh.write("utc\truntime_h\tload1\tmem_avail_gb\tgpu_util\tgpu_mem_gb\tclaude_rss_gb\tclaude_gpu_gb\ttokens_fresh\ttokens_cache_read\ttokens_output\tapi_calls\tprogress\teta_h\n")
            fh.write(f"{iso(now)}\t{el_h:.3f}\t{c['load1_5_15'][0]}\t{c['mem_avail_gb']}\t{c['gpu_util_pct']}\t{c['gpu_mem_used_gb']}\t{c['claude_proc_rss_gb']}\t{c['claude_gpu_mem_gb']}\t{tok['fresh']}\t{tok['cache_read']}\t{tok['output']}\t{tok['api_calls']}\t{pr['fraction']}\t{pr['eta_h']}\n")
        if c["mem_avail_gb"] < 3.0:
            emit(f"ALARM low memory: {c['mem_avail_gb']} GB available, claude RSS {c['claude_proc_rss_gb']} GB")
        if c["gpu_mem_used_gb"] and c["gpu_mem_used_gb"] > 14.5:
            emit(f"ALARM GPU memory {c['gpu_mem_used_gb']} GB used")
        if time.time() - last_hb > 3600:
            last_hb = time.time()
            emit(f"HEARTBEAT runtime={el_h:.2f}h progress={pr['fraction']} eta_h={pr['eta_h']} tokens_fresh={tok['fresh']} cache_read={tok['cache_read']} mem_avail={c['mem_avail_gb']}GB gpu={c['gpu_util_pct']}%")
        time.sleep(PERIOD)


if __name__ == "__main__":
    main()
"
